cd .semantic_index && python - <<'EOF'
import re
terms = ['immune system respond','viral infection','antiviral','interferon','adaptive immunity','innate immunity','immune response to virus','immune response','T cell','antibody','virus']
counts={}
import json
hits={t:[] for t in terms}
with open('docs.jsonl',encoding='utf-8') as f:
    for line in f:
        d=json.loads(line)
        txt=d['text'].lower()
        for t in terms:
            if t in txt:
                hits[t].append(d['id'])
for t in terms:
    print(f"{t!r}: {len(hits[t])}")
EOF
